function Badge({value,children}:{value:string,children?:ReactNode}){const c=['pass','verified','closed','active'].includes(value)?'green':['exception','hold','suspended','expired'].includes(value)?'red':['pending','open','assigned','awaiting_review'].includes(value)?'orange':'blue';return <span className={'badge '+c}>{children||statusName[value]||value}</span>}
function Picker({value,onChange,options,placeholder='Select…',label}:{value:any,onChange:(v:string)=>void,options:{value:string,label:string}[],placeholder?:string,label?:string}){return <Select value={value||''} onValueChange={onChange}><SelectTrigger aria-label={label||placeholder}><SelectValue placeholder={placeholder}/></SelectTrigger><SelectContent>{options.map(o=><SelectItem key={o.value} value={o.value}>{o.label}</SelectItem>)}</SelectContent></Select>}
